@startuml

class Line {
  + Name
}

class Piece {
  + Type
  + Reference
  + SellingPrice
}

class Component {
  + Code
  + ManufacturingPrice
  + Type
}

class PieceComponent {
  + Quantity
}

class Store {
  + Address
  + FaxNumber
}

class Order {
  + OrderNumber
  + Date
}

Order "*" -- "1" Store : places
Line "1" -- "*" Piece : produces
Piece "1" *-- "*" PieceComponent : composed of
PieceComponent "*" -- "1" Component : uses
Order "*" -- "1" Store : placed by
Order "1" -- "*" PieceComponent : contains
PieceComponent "*" -- "1" Piece : refers to

@enduml

